22	    type Item = T;
23	    type Iter = IntoIter<T>;
24	
25	    fn into_par_iter(self) -> Self::Iter {
26	        // NOTE: requires data movement if the deque doesn't start at offset 0.
27	        let inner = Vec::from(self).into_par_iter();
28	        IntoIter { inner }
29	    }
30	}
