91	/// Draining parallel iterator that moves a range out of a double-ended queue,
92	/// but keeps the total capacity.
93	#[derive(Debug)]
94	pub struct Drain<'a, T> {
95	    deque: &'a mut VecDeque<T>,
96	    range: Range<usize>,
97	    orig_len: usize,
98	}
99	
